    }

    var mirrorsInRightToLeftLayout: Bool {
        switch self {
        case .arrowUpRight, .chevronLeft, .chevronRight, .externalLink, .login, .logout, .sidebarOpen, .sidebarClose, .undo:
            true
        default:
            false
        }
    }
